function olCoreGetHeader(headers, name) {
    if (headers == null) {
        return '';
    }

    var value = headers.getHeader(name);
    return value == null ? '' : String(value);
}

function olCoreReadHttpRequest(source, rawBody) {
    var uri = String(source.get('uri') || '');
    var queryIndex = uri.indexOf('?');

    return {
        method: String(source.get('method') || '').toUpperCase(),
        path: (
            queryIndex >= 0 ? uri.substring(0, queryIndex) : uri
        ).toLowerCase(),
        query: queryIndex >= 0 ? uri.substring(queryIndex) : '',
        body: String(rawBody),
        authorization: olCoreGetHeader(
            source.get('headers'),
            'Authorization'
        )
    };
}

function olCoreSetGatewayError(target, status, code, diagnostics) {
    var statusText = String(status);

    if (!/^[45][0-9][0-9]$/.test(statusText)) {
        throw new Error('olCoreSetGatewayError: HTTP status must be 400-599');
    }
    if (code == null || String(code) === '' ||
        diagnostics == null || String(diagnostics) === '') {
        throw new Error('olCoreSetGatewayError: code and diagnostics are required');
    }

    target.put('gatewayError', JSON.stringify({
        resourceType: 'OperationOutcome',
        issue: [{
            severity: 'error',
            code: String(code),
            diagnostics: String(diagnostics)
        }]
    }));
    target.put('gatewayErrorStatusCode', statusText);
}
